with filtered_stores as (select * from stores where region = 'North'), opened_month_summary as (select date_trunc('MONTH', opened_date) as opened_month, round((100 * sum(case when region = 'Central' then 1 else 0 end)) / count(*), 1) as pct_central from filtered_stores group by date_trunc('MONTH', opened_date)) select * from opened_month_summary where pct_central >= 66 order by opened_month;
